document.querySelector('[data-share]')?.addEventListener('click',async()=>{const status=document.querySelector('#share-status');try{if(navigator.share){await navigator.share({title:document.title,url:location.href});}else{await navigator.clipboard.writeText(location.href);status.textContent='Đã sao chép liên kết.';}}catch(e){if(e.name!=='AbortError')status.textContent='Bạn có thể sao chép URL trên thanh địa chỉ để chia sẻ.';}});